style.css:
@-moz-document url-prefix("https://docs.google.com/spreadsheets/") {
/* --- 1. Bubble Blue Toolbars & Headers --- */
    /* Target the top headers, toolbars, and formula bar */
    #docs-header, 
    #docs-toolbar-wrapper, 
    #formula-bar {
        background: linear-gradient(135deg, #e0f7fa 0%, #b2ebf2 100%) !important;
        border-radius: 25px !important;
        margin: 6px !important;
        box-shadow: 0 5px 15px rgba(0, 188, 212, 0.2), inset 0 2px 5px rgba(255, 255, 255, 0.8) !important;
        border: 1px solid #80deea !important;
    }

    /* Make top buttons look like little circular bubbles */
    .goog-toolbar-button, 
    .goog-toolbar-menu-button {
        border-radius: 50% !important; 
        transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
        margin: 0 2px !important;
    }

    .goog-toolbar-button:hover, 
    .goog-toolbar-menu-button:hover {
        background: linear-gradient(145deg, #4dd0e1, #26c6da) !important;
        transform: scale(1.15) translateY(-2px) !important;
        box-shadow: 0 4px 8px rgba(0, 188, 212, 0.4) !important;
    }

    /* --- 2. Bubbly Sheet Tabs (Bottom) --- */
    .docs-sheet-tab {
        border-radius: 20px 20px 0 0 !important;
        background: #e0f7fa !important;
        border: 1px solid #b2ebf2 !important;
        border-bottom: none !important;
        margin-right: 2px !important;
        transition: background 0.2s ease !important;
    }

    .docs-sheet-active-tab {
        background: #00bcd4 !important;
        color: white !important;
        box-shadow: 0 -3px 10px rgba(0, 188, 212, 0.3) !important;
    }

    /* --- 3. Rising & Popping Bubble Animations --- */
    /* Create floating bubbles over the whole page */
    body::before, body::after {
        content: '';
        position: fixed;
        bottom: -60px;
        border-radius: 50%;
        background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.95), rgba(0, 188, 212, 0.3));
        box-shadow: inset 0 0 10px rgba(255,255,255,0.9), 0 4px 10px rgba(0,188,212,0.2);
        
        /* This prevents the bubbles from blocking your clicks! */
        pointer-events: none !important; 
        z-index: 99999 !important;
    }

    /* Bubble 1 Settings */
    body::before {
        left: 15%;
        width: 40px;
        height: 40px;
        animation: bubbleRiseAndPop 8s infinite ease-in;
    }

    /* Bubble 2 Settings */
    body::after {
        left: 80%;
        width: 60px;
        height: 60px;
        animation: bubbleRiseAndPop 12s infinite ease-in;
        animation-delay: 4s;
    }

    /* The Animation Keyframes */
    @keyframes bubbleRiseAndPop {
        0% {
            transform: translateY(0) scale(0.5);
            opacity: 0;
        }
        10% {
            opacity: 0.8; /* Fade in as it starts rising */
        }
        70% {
            transform: translateY(-70vh) scale(1.1) translateX(20px);
            opacity: 0.7;
        }
        90% {
            transform: translateY(-90vh) scale(1.4) translateX(-10px);
            opacity: 0.8; 
        }
        95% {
            transform: translateY(-95vh) scale(1.8); /* Expanding right before pop */
            opacity: 0; /* The "Pop" */
        }
        100% {
            transform: translateY(-100vh) scale(1.8);
            opacity: 0;
        }
    }
}
